WITH cleaned AS (SELECT *, TO_DATE(started_at) AS started_at_date FROM sessions WHERE started_at > TIMESTAMP '2024-03-01 16:00:00'), flagged AS (SELECT *, CASE WHEN started_at - LAG(started_at) OVER (PARTITION BY customer_id ORDER BY started_at, id) > INTERVAL '14' DAY THEN 1 ELSE 0 END AS is_new_session FROM cleaned), sessionized AS (SELECT *, SUM(is_new_session) OVER (PARTITION BY customer_id ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM flagged) SELECT CASE WHEN is_new_session >= 1 THEN 'PREMIUM' ELSE 'STANDARD' END AS is_new_session_tier, DATE_TRUNC('YEAR', started_at) AS year_start, (UNIX_TIMESTAMP(MAX(started_at)) - UNIX_TIMESTAMP(MIN(started_at))) / 60 AS duration_min, SORT_ARRAY(COLLECT_SET(device)) AS device_list, MAX(is_new_session) FILTER (WHERE country = 'US') AS us_max_is_new_session FROM sessionized GROUP BY is_new_session_tier, year_start ORDER BY year_start DESC
